  /** Time spent chopping per load. */
  readonly woodChopTime: number;
  /** Initial gold in a fresh mine. */
  readonly mineGold: number;
  /** Initial wood in a fresh forest tile. */
  readonly forestWood: number;
  /** Repair HP per sim-second. */
