    }
  }
  return best ? { x: best.x, y: best.y } : null;
}

export function isAdjacent(ax: number, ay: number, bx: number, by: number): boolean {
  const dx = Math.abs(ax - bx);
  const dy = Math.abs(ay - by);
  return dx <= 1 && dy <= 1;
}

export function pathStepTowards(
