// Order handler: the per-unit state machine that consumes an issued Order
// and produces observable progress. The unit's state is in
// UnitOrderState; this module is a pure function of (world, unit, dt) that
// advances it.

import { World } from "./world.js";
import { BuildingEntity, UnitEntity, isBuilding, isUnit } from "./entities.js";
import {
  AttackMoveOrder,
  AttackOrder,
  BuildOrder,
  HarvestOrder,
  MoveOrder,
  Order,
  OrderPhase,
  RepairOrder,
  TrainOrder,
} from "./orders.js";
import { findPath, octile } from "./pathfinding.js";
import { getBuildingStats, getUnitStats, HARVEST, TICK_DT, SIM_CONSTANTS } from "./stats.js";
import { TILE, isResourceTile, isWalkableTile } from "./tiles.js";
import { buildTerrainBlockedMap, isAdjacent, pathStepTowards, pickAdjacentWalkable } from "./helpers.js";

const ORDER_RETRY_LIMIT = 3;

function unitBlocksForWorld(world: World, selfId: number): Uint8Array {
  // Base: terrain + buildings.
  const blocked = buildTerrainBlockedMap(world);
  // Add other units' tiles as blocked.
  for (const e of world.entities.values()) {
    if (e.kind !== "unit") continue;
    if (e.id === selfId) continue;
    blocked[e.y * world.map.width + e.x] = 1;
  }
  return blocked;
}

function nearestDropOff(
  world: World,
  unit: UnitEntity,
  resource: "gold" | "wood",
): BuildingEntity | null {
  let best: BuildingEntity | null = null;
  let bestD = Infinity;
  for (const e of world.entities.values()) {
    if (e.kind !== "building") continue;
    if (e.faction !== unit.faction) continue;
    if (e.construction < 1) continue;
    if (resource === "gold" && e.buildingKind !== "townhall") continue;
    if (resource === "wood" && e.buildingKind !== "townhall" && e.buildingKind !== "lumbermill") continue;
    const d = octile(unit.x, unit.y, e.x + 0, e.y + 0);
    if (d < bestD) {
      bestD = d;
      best = e;
    }
  }
  return best;
}

function nearestSource(
  world: World,
  unit: UnitEntity,
  resource: "gold" | "wood",
  exclude: ReadonlySet<number>,
): { x: number; y: number } | null {
  let best: { x: number; y: number; d: number } | null = null;
  for (let y = 0; y < world.map.height; y++) {
    for (let x = 0; x < world.map.width; x++) {
      const t = world.map.get(x, y);
      if (resource === "gold" && t !== TILE.GOLD_MINE) continue;
      if (resource === "wood" && t !== TILE.FOREST) continue;
      const key = y * world.map.width + x;
      if (exclude.has(key)) continue;
      if (resource === "gold" && (world.map.mineGold[key] ?? 0) <= 0) continue;
      if (resource === "wood" && (world.map.forestWood[key] ?? 0) <= 0) continue;
      const d = octile(unit.x, unit.y, x, y);
      if (best === null || d < best.d) best = { x, y, d };
    }
  }
  return best;
}

function nearestEmptyWalkableAdjacentToSource(
  world: World,
  sourceX: number,
  sourceY: number,
  blocked: Uint8Array,
  selfId: number,
): { x: number; y: number } | null {
  const w = world.map.width;
  let best: { x: number; y: number; d: number } | null = null;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue;
      const x = sourceX + dx;
      const y = sourceY + dy;
      if (x < 0 || y < 0 || x >= world.map.width || y >= world.map.height) continue;
      if (blocked[y * w + x] === 1) continue;
      if (!isWalkableTile(world.map.get(x, y))) continue;
      // Must also be free of other units.
      let occupied = false;
      for (const e of world.entities.values()) {
        if (e.kind !== "unit") continue;
        if (e.id === selfId) continue;
        if (e.x === x && e.y === y) {
          occupied = true;
          break;
        }
      }
      if (occupied) continue;
      const d = dx * dx + dy * dy;
      if (best === null || d < best.d) best = { x, y, d };
    }
  }
  return best;
}

function trySetOrder(
  world: World,
  unit: UnitEntity,
  order: Order,
  blocked: Uint8Array,
): boolean {
  unit.orderState.order = order;
  unit.orderState.path = [];
  unit.orderState.moveProgress = 0;
  unit.orderState.workProgress = 0;
  unit.orderState.repathAttempts = 0;
  unit.orderState.cargo = { gold: 0, wood: 0 };
  unit.orderState.watchdog = 0;
  unit.target = null;
  unit.moveGoal = null;

  if (order.kind === "move" || order.kind === "attackMove") {
    const goal = order as MoveOrder | AttackMoveOrder;
    const path = findPath(world.map, unit.x, unit.y, goal.x, goal.y, { blocked });
    if (path === null) {
      // C4: try the nearest reachable point via BFS.
      const near = nearestReachableTile(world, blocked, unit.x, unit.y, goal.x, goal.y);
      if (near === null) {
        // Truly unreachable — go idle.
        unit.orderState.order = null;
        unit.orderState.phase = "idle";
        return false;
      }
      const path2 = findPath(world.map, unit.x, unit.y, near.x, near.y, { blocked });
      if (path2 === null) {
        unit.orderState.order = null;
        unit.orderState.phase = "idle";
        return false;
      }
      unit.orderState.path = path2;
      unit.orderState.phase = order.kind === "attackMove" ? "patrolling" : "moving";
    } else {
      unit.orderState.path = path;
      unit.orderState.phase = order.kind === "attackMove" ? "patrolling" : "moving";
    }
  } else if (order.kind === "attack") {
    const target = world.entities.get((order as AttackOrder).target);
    if (!target || (target.kind !== "unit" && target.kind !== "building") || target.faction === unit.faction) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    unit.target = target.id;
    unit.orderState.phase = "attacking";
  } else if (order.kind === "harvest") {
    const h = order as HarvestOrder;
    const t = world.map.get(h.tx, h.ty);
    if (!isResourceTile(t)) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    // Set phase to "moving" — the unit walks to an adjacent walkable tile.
    const adj = pickAdjacentWalkable(world, h.tx, h.ty, blocked);
    if (adj === null) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    unit.orderState.path = path;
    unit.orderState.phase = "gathering";
  } else if (order.kind === "build") {
    const b = order as BuildOrder;
    const stats = getBuildingStats(unit.faction, b.building);
    // Verify placement.
    if (!isBuildableAt(world, b.x, b.y, stats.footprint.w, stats.footprint.h, unit.faction, unit.id)) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    // Pay cost.
    if (!canPay(world, unit.faction, stats.goldCost, stats.woodCost)) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    pay(world, unit.faction, stats.goldCost, stats.woodCost);
    const build = world.spawnBuilding(unit.faction, b.building, b.x, b.y, 0, unit.id);
    build.trainQueue = [];
    // Reserve a path: unit walks adjacent and builds.
    const adj = findAdjacentWalkableToFootprint(world, blocked, b.x, b.y, stats.footprint.w, stats.footprint.h);
    if (adj === null) {
      world.removeEntity(build.id);
      refund(world, unit.faction, stats.goldCost, stats.woodCost);
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      world.removeEntity(build.id);
      refund(world, unit.faction, stats.goldCost, stats.woodCost);
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    unit.orderState.path = path;
    unit.orderState.phase = "building";
  } else if (order.kind === "repair") {
    const r = order as RepairOrder;
    const target = world.entities.get(r.target);
    if (!target || !isBuilding(target) || target.faction !== unit.faction) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    unit.target = target.id;
    unit.orderState.phase = "repairing";
  } else if (order.kind === "train") {
    // Train orders are consumed at the building level, not the unit level.
    unit.orderState.order = null;
    unit.orderState.phase = "idle";
    return false;
  }
  return true;
}

function isBuildableAt(
  world: World,
  x: number,
  y: number,
  w: number,
  h: number,
  faction: string,
  workerId: number,
): boolean {
  const map = world.map;
  for (let dy = 0; dy < h; dy++) {
    for (let dx = 0; dx < w; dx++) {
      const xx = x + dx;
      const yy = y + dy;
      if (!map.inBounds(xx, yy)) return false;
      if (!isWalkableTile(map.get(xx, yy))) return false;
      if (isResourceTile(map.get(xx, yy))) return false;
    }
  }
  // No overlap with existing buildings.
  for (const e of world.entities.values()) {
    if (e.kind !== "building") continue;
    if (e.construction < 1) continue;
    const stats = getBuildingStats(e.faction, e.buildingKind);
    if (rectsOverlap(x, y, w, h, e.x, e.y, stats.footprint.w, stats.footprint.h)) return false;
  }
  // No unit on the footprint (except the building worker itself).
  for (const e of world.entities.values()) {
    if (e.kind !== "unit") continue;
    if (e.id === workerId) continue;
    if (e.x >= x && e.x < x + w && e.y >= y && e.y < y + h) return false;
  }
  void faction;
  return true;
}

function rectsOverlap(
  ax: number, ay: number, aw: number, ah: number,
  bx: number, by: number, bw: number, bh: number,
): boolean {
  return ax < bx + bw && ax + aw > bx && ay < by + bh && ay + ah > by;
}

function findAdjacentWalkableToFootprint(
  world: World,
  blocked: Uint8Array,
  x: number, y: number, w: number, h: number,
): { x: number; y: number } | null {
  const W = world.map.width;
  const H = world.map.height;
  for (let dy = -1; dy <= h; dy++) {
    for (let dx = -1; dx <= w; dx++) {
      // perimeter only
      const onLeft = dx === -1;
      const onRight = dx === w;
      const onTop = dy === -1;
      const onBottom = dy === h;
      if (!onLeft && !onRight && !onTop && !onBottom) continue;
      const px = x + dx;
      const py = y + dy;
      if (px < 0 || py < 0 || px >= W || py >= H) continue;
      if (blocked[py * W + px] === 1) continue;
      if (!isWalkableTile(world.map.get(px, py))) continue;
      return { x: px, y: py };
    }
  }
  return null;
}

function nearestReachableTile(
  world: World,
  blocked: Uint8Array,
  sx: number, sy: number, gx: number, gy: number,
): { x: number; y: number } | null {
  // BFS outward from gx,gy up to a bounded radius, return first reachable.
  const W = world.map.width;
  const H = world.map.height;
  const visited = new Uint8Array(W * H);
  const queue: Array<[number, number]> = [[gx, gy]];
  let head = 0;
  let safety = 200;
  while (head < queue.length && safety-- > 0) {
    const [x, y] = queue[head++] as [number, number];
    if (x < 0 || y < 0 || x >= W || y >= H) continue;
    if (visited[y * W + x] === 1) continue;
    visited[y * W + x] = 1;
    if (blocked[y * W + x] === 0 && isWalkableTile(world.map.get(x, y))) {
      // Try to path to it.
      const path = findPath(world.map, sx, sy, x, y, { blocked });
      if (path !== null) return { x, y };
    }
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx;
        const ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue;
        if (visited[ny * W + nx] === 1) continue;
        queue.push([nx, ny]);
      }
    }
  }
  return null;
}

function canPay(world: World, faction: "humans" | "orcs", gold: number, wood: number): boolean {
  const p = world.players[faction];
  return p.gold >= gold && p.wood >= wood;
}

function pay(world: World, faction: "humans" | "orcs", gold: number, wood: number): void {
  const p = world.players[faction];
  p.gold -= gold;
  p.wood -= wood;
}

function refund(world: World, faction: "humans" | "orcs", gold: number, wood: number): void {
  const p = world.players[faction];
  p.gold += gold;
  p.wood += wood;
}

/** Public: issue an order to a single unit. Returns true if the order was
 *  accepted (i.e. entered a non-idle phase). */
export function issueOrder(world: World, unitId: number, order: Order): boolean {
  const unit = world.entities.get(unitId);
  if (!unit || !isUnit(unit)) return false;
  const blocked = unitBlocksForWorld(world, unit.id);
  return trySetOrder(world, unit, order, blocked);
}

void TICK_DT;
void SIM_CONSTANTS;
void AttackMoveOrder;
void BuildOrder;
void HarvestOrder;
void MoveOrder;
void RepairOrder;
void TrainOrder;
void Order;
void OrderPhase;
void UnitOrderState;
void ORDER_RETRY_LIMIT;

// Unit step: advances a single unit by one tick. Called by the world's
// step() function for every unit. This is where all order state-machine
// transitions happen, including movement, gathering, building, repair, attack.
//
// Design rules enforced here:
//  - I1 (no tunneling): units only move onto walkable terrain.
//  - I4 (no shove): movement decisions only consider self + terrain, not
//    other units; congestion is resolved by waiting then repathing.
//  - I3 (order liveness): every order either makes observable progress or
//    transitions to idle within the watchdog window.

import { World } from "./world.js";
import { BuildingEntity, UnitEntity, isBuilding, isUnit, isProjectile } from "./entities.js";
import { TILE, isResourceTile, isWalkableTile } from "./tiles.js";
import { findPath, octile } from "./pathfinding.js";
import { getBuildingStats, getUnitStats, HARVEST, TICK_DT } from "./stats.js";
import { Order } from "./orders.js";
import { buildTerrainBlockedMap, isAdjacent, pathStepTowards, pickAdjacentWalkable } from "./helpers.js";

const HALF_TILE = 0.5;

function tileFreeOfOtherUnits(world: World, x: number, y: number, selfId: number): boolean {
  for (const e of world.entities.values()) {
    if (e.kind !== "unit") continue;
    if (e.id === selfId) continue;
    if (e.x === x && e.y === y) return false;
  }
  return true;
}

function unitBlocks(world: World, selfId: number): Uint8Array {
  const arr = buildTerrainBlockedMap(world);
  for (const e of world.entities.values()) {
    if (e.kind !== "unit") continue;
    if (e.id === selfId) continue;
    arr[e.y * world.map.width + e.x] = 1;
  }
  return arr;
}

function nearestDropOffBuilding(
  world: World,
  unit: UnitEntity,
  resource: "gold" | "wood",
): BuildingEntity | null {
  let best: BuildingEntity | null = null;
  let bestD = Infinity;
  for (const e of world.entities.values()) {
    if (e.kind !== "building") continue;
    if (e.faction !== unit.faction) continue;
    if (e.construction < 1) continue;
    if (resource === "gold" && e.buildingKind !== "townhall") continue;
    if (
      resource === "wood" &&
      e.buildingKind !== "townhall" &&
      e.buildingKind !== "lumbermill"
    ) continue;
    const d = octile(unit.x, unit.y, e.x, e.y);
    if (d < bestD) {
      bestD = d;
      best = e;
    }
  }
  return best;
}

function findWalkableTileAdjacentToSource(
  world: World,
  blocked: Uint8Array,
  sx: number, sy: number,
  selfId: number,
): { x: number; y: number } | null {
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue;
      const x = sx + dx;
      const y = sy + dy;
      if (x < 0 || y < 0 || x >= world.map.width || y >= world.map.height) continue;
      if (blocked[y * world.map.width + x] === 1) continue;
      if (!isWalkableTile(world.map.get(x, y))) continue;
      if (!tileFreeOfOtherUnits(world, x, y, selfId)) continue;
      return { x, y };
    }
  }
  return null;
}

function retargetHarvestSource(
  world: World,
  unit: UnitEntity,
  resource: "gold" | "wood",
  blocked: Uint8Array,
): boolean {
  let best: { x: number; y: number; d: number } | null = null;
  for (let y = 0; y < world.map.height; y++) {
    for (let x = 0; x < world.map.width; x++) {
      const t = world.map.get(x, y);
      if (resource === "gold" && t !== TILE.GOLD_MINE) continue;
      if (resource === "wood" && t !== TILE.FOREST) continue;
      const idx = y * world.map.width + x;
      if (resource === "gold" && (world.map.mineGold[idx] ?? 0) <= 0) continue;
      if (resource === "wood" && (world.map.forestWood[idx] ?? 0) <= 0) continue;
      const d = octile(unit.x, unit.y, x, y);
      if (best === null || d < best.d) best = { x, y, d };
    }
  }
  if (best === null) return false;
  const adj = findWalkableTileAdjacentToSource(world, blocked, best.x, best.y, unit.id);
  if (adj === null) return false;
  const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
  if (path === null) return false;
  unit.orderState.order = {
    kind: "harvest",
    tx: best.x,
    ty: best.y,
  } as Order;
  unit.orderState.path = path;
  unit.orderState.repathAttempts = 0;
  unit.orderState.phase = "gathering";
  return true;
}

function stepAlongPath(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  if (unit.orderState.path.length === 0) {
    // No path: in some phases this means "arrived".
    return;
  }
  const stats = getUnitStats(unit.faction, unit.unitKind);
  const speed = stats.moveSpeed; // tiles per second
  // Resolve collisions: do not enter a tile currently occupied by another unit.
  let moved = false;
  let guard = 0;
  let progress = unit.orderState.moveProgress;
  while (progress < dt * speed && guard++ < 8) {
    const next = unit.orderState.path[0];
    if (!next) break;
    const [nx, ny] = next;
    // Sanity: never move into unwalkable terrain.
    if (!isWalkableTile(world.map.get(nx, ny))) {
      // Drop this path: repath or idle.
      unit.orderState.path = [];
      return;
    }
    // I1: no diagonal corner cutting.
    const fromX = unit.x;
    const fromY = unit.y;
    if (nx !== fromX && ny !== fromY) {
      if (
        !isWalkableTile(world.map.get(fromX, ny)) ||
        !isWalkableTile(world.map.get(nx, fromY))
      ) {
        // Would corner-cut: skip this step by going axial first.
        const axial = findAxialDetour(world, blocked, fromX, fromY, nx, ny, unit.id);
        if (axial !== null) {
          unit.orderState.path.unshift(axial);
          continue;
        }
        unit.orderState.path = [];
        return;
      }
    }
    // I4: do not displace other units. Wait one tick if occupied.
    if (!tileFreeOfOtherUnits(world, nx, ny, unit.id)) {
      // Wait: end movement for this tick. Path stays.
      return;
    }
    const remaining = dt * speed - progress;
    // Compute step cost.
    const dx = nx - fromX;
    const dy = ny - fromY;
    const stepCost = dx !== 0 && dy !== 0 ? Math.SQRT2 : 1;
    if (remaining >= stepCost) {
      // Move into the new tile.
      unit.x = nx;
      unit.y = ny;
      unit.subX = 0.5;
      unit.subY = 0.5;
      progress += stepCost;
      unit.orderState.path.shift();
      moved = true;
      // Sub-tile jitter for visual variety.
      const jitter = (world.rng.next() - 0.5) * 0.1;
      const jitterY = (world.rng.next() - 0.5) * 0.1;
      unit.subX = Math.max(0.05, Math.min(0.95, 0.5 + jitter));
      unit.subY = Math.max(0.05, Math.min(0.95, 0.5 + jitterY));
    } else {
      // Partial sub-tile step.
      const frac = remaining / stepCost;
      unit.subX = 0.5 + (nx - fromX) * frac;
      unit.subY = 0.5 + (ny - fromY) * frac;
      progress = dt * speed;
    }
  }
  unit.orderState.moveProgress = progress;
  if (unit.orderState.path.length === 0) {
    unit.subX = 0.5;
    unit.subY = 0.5;
  }
  if (moved) {
    // No-op: position changed in place above.
    void moved;
  }
}

function findAxialDetour(
  world: World,
  blocked: Uint8Array,
  fromX: number, fromY: number,
  toX: number, toY: number,
  selfId: number,
): [number, number] | null {
  // Try stepping to (toX, fromY) or (fromX, toY).
  const c1 = isWalkableTile(world.map.get(toX, fromY)) && tileFreeOfOtherUnits(world, toX, fromY, selfId);
  const c2 = isWalkableTile(world.map.get(fromX, toY)) && tileFreeOfOtherUnits(world, fromX, toY, selfId);
  if (c1 && blocked[fromY * world.map.width + toX] === 0) return [toX, fromY];
  if (c2 && blocked[toY * world.map.width + fromX] === 0) return [fromX, toY];
  return null;
}

function tryAttack(world: World, unit: UnitEntity, target: number): void {
  const t = world.entities.get(target);
  if (!t) {
    unit.target = null;
    return;
  }
  const dmg = getUnitStats(unit.faction, unit.unitKind).damage;
  if (t.kind === "unit") {
    const armor = getUnitStats(t.faction, t.unitKind).armor;
    const actual = Math.max(1, dmg - armor);
    t.hp -= actual;
    unit.damageDealt += actual;
    if (t.hp <= 0) {
      world.removeEntity(t.id);
      world.players[t.faction].unitsLost++;
      world.players[unit.faction].kills++;
      // Free supply.
      const stats = getUnitStats(t.faction, t.unitKind);
      world.players[t.faction].supplyUsed = Math.max(0, world.players[t.faction].supplyUsed - stats.supplyCost);
    }
  } else if (t.kind === "building") {
    const b = t as BuildingEntity;
    const armor = 0; // buildings have no armor stat in this game
    const actual = Math.max(1, dmg - armor);
    b.hp -= actual;
    unit.damageDealt += actual;
    if (b.hp <= 0) {
      destroyBuilding(world, b);
    }
  } else {
    // Projectile target: invalid.
    unit.target = null;
  }
}

function destroyBuilding(world: World, b: BuildingEntity): void {
  const p = world.players[b.faction];
  p.buildingsLost++;
  p.supplyUsed = Math.max(0, p.supplyUsed - 0); // buildings don't take supply
  // Remove from map footprint (treat as no longer solid).
  world.removeEntity(b.id);
  world.recomputeSupplyCap(b.faction);
  // I2 bookkeeping: supplyUsed may now exceed cap; that's allowed transiently.
}

function autoAcquireTarget(world: World, unit: UnitEntity): void {
  const stats = getUnitStats(unit.faction, unit.unitKind);
  let best: { id: number; d: number } | null = null;
  for (const e of world.entities.values()) {
    if (e.faction === unit.faction) continue;
    if (e.kind !== "unit" && e.kind !== "building") continue;
    if (e.kind === "building" && e.construction < 1) continue;
    const tx = e.kind === "unit" ? e.x : (e as BuildingEntity).x;
    const ty = e.kind === "unit" ? e.y : (e as BuildingEntity).y;
    const d = octile(unit.x, unit.y, tx, ty);
    if (d > stats.sightRadius) continue;
    if (best === null || d < best.d) best = { id: e.id, d };
  }
  unit.target = best ? best.id : null;
}

function stepGather(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  const order = unit.orderState.order as { kind: "harvest"; tx: number; ty: number } | null;
  if (!order) {
    unit.orderState.phase = "idle";
    return;
  }
  if (unit.orderState.path.length > 0) {
    stepAlongPath(world, unit, blocked, dt);
    return;
  }
  // Arrived adjacent to source.
  if (!isAdjacent(unit.x, unit.y, order.tx, order.ty)) {
    // Source moved (no, source is a tile). Maybe we got pushed — repath.
    const adj = findWalkableTileAdjacentToSource(world, blocked, order.tx, order.ty, unit.id);
    if (adj === null) {
      unit.orderState.phase = "idle";
      return;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      unit.orderState.phase = "idle";
      return;
    }
    unit.orderState.path = path;
    return;
  }
  // Gather progress.
  const t = world.map.get(order.tx, order.ty);
  if (t === TILE.GOLD_MINE) {
    const idx = order.ty * world.map.width + order.tx;
    if ((world.map.mineGold[idx] ?? 0) <= 0) {
      // Mine exhausted: retarget.
      if (!retargetHarvestSource(world, unit, "gold", blocked)) {
        // No more mines: try deliver what we have, else idle.
        if (unit.orderState.cargo.gold > 0) {
          returnFromHarvest(world, unit, blocked, "gold");
        } else {
          unit.orderState.phase = "idle";
        }
      }
      return;
    }
    unit.orderState.workProgress += dt;
    if (unit.orderState.workProgress >= HARVEST.goldGatherTime) {
      unit.orderState.workProgress = 0;
      const carry = Math.min(HARVEST.goldPerTrip, world.map.mineGold[idx] ?? 0);
      world.map.mineGold[idx] = Math.max(0, (world.map.mineGold[idx] ?? 0) - carry);
      unit.orderState.cargo.gold += carry;
      // Mine depleted?
      if ((world.map.mineGold[idx] ?? 0) <= 0) {
        world.map.set(order.tx, order.ty, TILE.DEPLETED_MINE);
        // I1 invariant: depleted mine is unwalkable (see tiles.ts). Verify pathing.
      }
      returnFromHarvest(world, unit, blocked, "gold");
    }
  } else if (t === TILE.FOREST) {
    const idx = order.ty * world.map.width + order.tx;
    if ((world.map.forestWood[idx] ?? 0) <= 0) {
      // Forest depleted: retarget to nearest other forest.
      if (!retargetHarvestSource(world, unit, "wood", blocked)) {
        if (unit.orderState.cargo.wood > 0) {
          returnFromHarvest(world, unit, blocked, "wood");
        } else {
          unit.orderState.phase = "idle";
        }
      }
      return;
    }
    unit.orderState.workProgress += dt;
    if (unit.orderState.workProgress >= HARVEST.woodChopTime) {
      unit.orderState.workProgress = 0;
      const carry = Math.min(HARVEST.woodPerTrip, world.map.forestWood[idx] ?? 0);
      world.map.forestWood[idx] = Math.max(0, (world.map.forestWood[idx] ?? 0) - carry);
      unit.orderState.cargo.wood += carry;
      if ((world.map.forestWood[idx] ?? 0) <= 0) {
        world.map.set(order.tx, order.ty, TILE.STUMP);
      }
      returnFromHarvest(world, unit, blocked, "wood");
    }
  } else {
    // Source no longer valid.
    unit.orderState.phase = "idle";
  }
}

function returnFromHarvest(
  world: World,
  unit: UnitEntity,
  blocked: Uint8Array,
  resource: "gold" | "wood",
): void {
  const drop = nearestDropOffBuilding(world, unit, resource);
  if (!drop) {
    // No drop-off exists: stay put with cargo intact (C5).
    unit.orderState.phase = "idle";
    return;
  }
  const adj = findAdjacentWalkableToBuilding(world, blocked, drop, unit.id);
  if (adj === null) {
    unit.orderState.phase = "idle";
    return;
  }
  const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
  if (path === null) {
    unit.orderState.phase = "idle";
    return;
  }
  unit.orderState.path = path;
  unit.orderState.phase = "returning";
}

function findAdjacentWalkableToBuilding(
  world: World,
  blocked: Uint8Array,
  b: BuildingEntity,
  selfId: number,
): { x: number; y: number } | null {
  const stats = getBuildingStats(b.faction, b.buildingKind);
  const W = world.map.width;
  const H = world.map.height;
  for (let dy = -1; dy <= stats.footprint.h; dy++) {
    for (let dx = -1; dx <= stats.footprint.w; dx++) {
      const onLeft = dx === -1;
      const onRight = dx === stats.footprint.w;
      const onTop = dy === -1;
      const onBottom = dy === stats.footprint.h;
      if (!onLeft && !onRight && !onTop && !onBottom) continue;
      const x = b.x + dx;
      const y = b.y + dy;
      if (x < 0 || y < 0 || x >= W || y >= H) continue;
      if (blocked[y * W + x] === 1) continue;
      if (!isWalkableTile(world.map.get(x, y))) continue;
      if (!tileFreeOfOtherUnits(world, x, y, selfId)) continue;
      return { x, y };
    }
  }
  return null;
}

function stepReturn(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  if (unit.orderState.path.length > 0) {
    stepAlongPath(world, unit, blocked, dt);
    return;
  }
  // We have arrived. Deliver cargo.
  const order = unit.orderState.order as { kind: "harvest"; tx: number; ty: number } | null;
  const resource: "gold" | "wood" = order && world.map.get(order.tx, order.ty) === TILE.FOREST ? "wood" : "gold";
  // Re-validate drop-off still exists.
  const drop = nearestDropOffBuilding(world, unit, resource);
  if (!drop) {
    // C5: drop-off destroyed while carrying → stay put with cargo.
    unit.orderState.phase = "idle";
    return;
  }
  if (!isAdjacent(unit.x, unit.y, drop.x, drop.y)) {
    // Try rerouting.
    const adj = findAdjacentWalkableToBuilding(world, blocked, drop, unit.id);
    if (adj === null) {
      unit.orderState.phase = "idle";
      return;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      unit.orderState.phase = "idle";
      return;
    }
    unit.orderState.path = path;
    return;
  }
  if (resource === "gold") {
    world.players[unit.faction].gold += unit.orderState.cargo.gold;
    unit.orderState.cargo.gold = 0;
  } else {
    world.players[unit.faction].wood += unit.orderState.cargo.wood;
    unit.orderState.cargo.wood = 0;
  }
  // Loop back to source.
  if (!retargetHarvestSource(world, unit, resource, blocked)) {
    // No more sources: go idle near drop-off.
    unit.orderState.phase = "idle";
  }
}

function stepBuild(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  if (unit.orderState.path.length > 0) {
    stepAlongPath(world, unit, blocked, dt);
    return;
  }
  const order = unit.orderState.order as { kind: "build"; building: import("./stats.js").BuildingKind; x: number; y: number } | null;
  if (!order) {
    unit.orderState.phase = "idle";
    return;
  }
  const b = world.entities.get(unit.target ?? -1);
  // Find the building by top-left corner + faction.
  let build: BuildingEntity | null = null;
  for (const e of world.entities.values()) {
    if (e.kind !== "building") continue;
    if (e.faction !== unit.faction) continue;
    if (e.buildingKind !== order.building) continue;
    if (e.x === order.x && e.y === order.y) {
      build = e as BuildingEntity;
      break;
    }
  }
  if (!build) {
    unit.orderState.phase = "idle";
    return;
  }
  if (!isAdjacent(unit.x, unit.y, build.x, build.y)) {
    // Walk closer.
    const adj = findAdjacentWalkableToBuilding(world, blocked, build, unit.id);
    if (adj === null) {
      unit.orderState.phase = "idle";
      return;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      unit.orderState.phase = "idle";
      return;
    }
    unit.orderState.path = path;
    return;
  }
  void b;
  // Build progress.
  const stats = getBuildingStats(unit.faction, order.building);
  unit.orderState.workProgress += dt;
  const rate = 1 / Math.max(0.1, stats.buildTime);
  build.construction = Math.min(1, build.construction + rate * dt);
  if (build.construction >= 1) {
    // Complete: refund worker, refresh supply cap.
    build.builtBy = null;
    unit.orderState.phase = "idle";
    unit.orderState.order = null;
    world.recomputeSupplyCap(unit.faction);
  }
}

function stepRepair(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  if (unit.orderState.path.length > 0) {
    stepAlongPath(world, unit, blocked, dt);
    return;
  }
  const t = world.entities.get(unit.target ?? -1);
  if (!t || t.kind !== "building") {
    unit.orderState.phase = "idle";
    return;
  }
  const b = t as BuildingEntity;
  if (b.faction !== unit.faction) {
    unit.orderState.phase = "idle";
    return;
  }
  if (b.hp >= b.maxHp) {
    unit.orderState.phase = "idle";
    return;
  }
  if (!isAdjacent(unit.x, unit.y, b.x, b.y)) {
    // Move closer.
    const adj = findAdjacentWalkableToBuilding(world, blocked, b, unit.id);
    if (adj === null) {
      unit.orderState.phase = "idle";
      return;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      unit.orderState.phase = "idle";
      return;
    }
    unit.orderState.path = path;
    return;
  }
  // Repair: HP per sec, gold cost per sec.
  const cost = HARVEST.repairGoldPerSec * dt;
  if (world.players[unit.faction].gold < cost) {
    // Out of gold: stop and idle (without losing order in case gold comes back).
    return;
  }
  world.players[unit.faction].gold -= cost;
  b.hp = Math.min(b.maxHp, b.hp + HARVEST.repairRate * dt);
  if (b.hp >= b.maxHp) {
    unit.orderState.phase = "idle";
    unit.orderState.order = null;
  }
}

function stepCombat(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  const stats = getUnitStats(unit.faction, unit.unitKind);
  // Re-acquire if no target.
  if (unit.target === null || !world.entities.has(unit.target)) {
    autoAcquireTarget(world, unit);
  }
  // If a move order / attackMove, walk to the goal tile.
  if (unit.orderState.path.length > 0) {
    stepAlongPath(world, unit, blocked, dt);
  }
  if (unit.target !== null) {
    const t = world.entities.get(unit.target);
    if (!t) {
      unit.target = null;
      return;
    }
    const tx = t.kind === "unit" ? t.x : (t as BuildingEntity).x;
    const ty = t.kind === "unit" ? t.y : (t as BuildingEntity).y;
    const d = octile(unit.x, unit.y, tx, ty);
    if (d <= stats.attackRange) {
      // In range: face target, attack on cooldown.
      unit.orderState.attackCooldown -= dt;
      if (unit.orderState.attackCooldown <= 0) {
        if (stats.attackProjectile) {
          // Spawn projectile from unit to target.
          world.spawnProjectile(
            unit.faction,
            unit.id,
            t.id,
            unit.x + 0.5,
            unit.y + 0.5,
            8,
            stats.damage,
          );
        } else {
          tryAttack(world, unit, t.id);
        }
        unit.orderState.attackCooldown = stats.attackCooldown;
      }
    } else {
      // Out of range: chase.
      if (unit.orderState.path.length === 0) {
        const path = findPath(world.map, unit.x, unit.y, tx, ty, { blocked });
        if (path !== null) {
          unit.orderState.path = path;
        }
      }
    }
  }
}

function stepIdle(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  // Idle units auto-acquire targets (defensive).
  if (unit.target === null) {
    autoAcquireTarget(world, unit);
  }
  if (unit.target !== null) {
    unit.orderState.phase = "attacking";
    return;
  }
  // Buildings of your faction may also request action via attack-move orders
  // but a pure idle is just waiting.
  void blocked;
  void dt;
}

/** Public: step one unit one tick. */
export function stepUnit(world: World, unit: UnitEntity, dt: number): void {
  // Decay attack cooldown always.
  if (unit.orderState.attackCooldown > 0) unit.orderState.attackCooldown -= dt;
  if (unit.hp <= 0) {
    unit.corpseTimer += dt;
    if (unit.corpseTimer > 3) world.removeEntity(unit.id);
    return;
  }
  const blocked = unitBlocks(world, unit.id);
  // Watchdog: capture snapshot before phase step.
  const prev = {
    tx: unit.x,
    ty: unit.y,
    phase: unit.orderState.phase,
    cargoKey: `${unit.orderState.cargo.gold},${unit.orderState.cargo.wood}`,
  };
  switch (unit.orderState.phase) {
    case "moving":
    case "patrolling":
      stepAlongPath(world, unit, blocked, dt);
      // After moving, if attack-move, try acquire.
      if (unit.orderState.phase === "patrolling") {
        if (unit.target === null) autoAcquireTarget(world, unit);
        if (unit.target !== null) {
          unit.orderState.phase = "attacking";
        }
      }
      break;
    case "gathering":
      stepGather(world, unit, blocked, dt);
      break;
    case "returning":
      stepReturn(world, unit, blocked, dt);
      break;
    case "building":
      stepBuild(world, unit, blocked, dt);
      break;
    case "repairing":
      stepRepair(world, unit, blocked, dt);
      break;
    case "attacking":
      stepCombat(world, unit, blocked, dt);
      break;
    case "idle":
    default:
      stepIdle(world, unit, blocked, dt);
      break;
  }
  // Watchdog: detect lack of progress.
  if (unit.orderState.order !== null || unit.orderState.phase !== "idle") {
    unit.orderState.watchdog++;
  } else {
    unit.orderState.watchdog = 0;
  }
  if (unit.orderState.watchdog > 0) {
    const next = {
      tx: unit.x,
      ty: unit.y,
      phase: unit.orderState.phase,
      cargoKey: `${unit.orderState.cargo.gold},${unit.orderState.cargo.wood}`,
    };
    const progressed =
      next.tx !== prev.tx ||
      next.ty !== prev.ty ||
      next.phase !== prev.phase ||
      next.cargoKey !== prev.cargoKey;
    if (progressed) {
      unit.orderState.watchdog = 0;
      unit.orderState.lastSnapshot = next;
    } else if (unit.orderState.watchdog > SIM_CONSTANTS_PROGRESS_WATCHDOG) {
      // Force idle: re-target or give up.
      unit.orderState.phase = "idle";
      unit.orderState.order = null;
      unit.orderState.watchdog = 0;
    }
  }
}

// Local copy of the watchdog threshold (avoids importing SIM_CONSTANTS into a
// 500-line file). Must match stats.ts.
const SIM_CONSTANTS_PROGRESS_WATCHDOG = 600;

void TILE;
void isResourceTile;
void HALF_TILE;
void isProjectile;
void Order;
void pathStepTowards;
void pickAdjacentWalkable;

// Building and projectile step. Buildings: progress construction, train queue.
// Projectiles: travel to target, apply damage on arrival.
//
// I2 bookkeeping: training is rejected when supply would exceed cap; a
// completed unit consumes supply; a destroyed unit releases supply.

import { World } from "./world.js";
import { BuildingEntity, isBuilding, isProjectile, isUnit, ProjectileEntity, UnitEntity } from "./entities.js";
import { TILE } from "./tiles.js";
import { getBuildingStats, getUnitStats } from "./stats.js";
import { findPath, octile } from "./pathfinding.js";
import { TICK_DT } from "./stats.js";

const HALF_TILE = 0.5;

function trySpawnUnitAtAdjacentTile(
  world: World,
  b: BuildingEntity,
  kind: import("./stats.js").UnitKind,
): UnitEntity | null {
  const stats = getUnitStats(b.faction, kind);
  const cap = world.players[b.faction].supplyCap;
  const used = world.players[b.faction].supplyUsed;
  if (used + stats.supplyCost > cap) {
    return null; // can't exceed cap (I2: training blocked at cap)
  }
  // Find a free walkable tile adjacent to building, or nearby.
  const fp = getBuildingStats(b.faction, b.buildingKind).footprint;
  const candidates: Array<[number, number]> = [];
  for (let dy = -1; dy <= fp.h; dy++) {
    for (let dx = -1; dx <= fp.w; dx++) {
      const onLeft = dx === -1;
      const onRight = dx === fp.w;
      const onTop = dy === -1;
      const onBottom = dy === fp.h;
      if (!onLeft && !onRight && !onTop && !onBottom) continue;
      const x = b.x + dx;
      const y = b.y + dy;
      if (x < 0 || y < 0 || x >= world.map.width || y >= world.map.height) continue;
      candidates.push([x, y]);
    }
  }
  // Sort by distance from building center, then by "free" first.
  for (const [x, y] of candidates) {
    if (!isFreeTile(world, x, y)) continue;
    const u = world.spawnUnit(b.faction, kind, x, y);
    world.players[b.faction].supplyUsed += stats.supplyCost;
    return u;
  }
  // C6: try expanding the search outward in expanding rings.
  for (let r = 2; r <= 5; r++) {
    for (let dy = -r; dy <= r + fp.h - 1; dy++) {
      for (let dx = -r; dx <= r + fp.w - 1; dx++) {
        const onPerim =
          dx === -r || dy === -r || dx === r + fp.w - 1 || dy === r + fp.h - 1;
        if (!onPerim) continue;
        const x = b.x + dx;
        const y = b.y + dy;
        if (x < 0 || y < 0 || x >= world.map.width || y >= world.map.height) continue;
        if (!isFreeTile(world, x, y)) continue;
        const u = world.spawnUnit(b.faction, kind, x, y);
        world.players[b.faction].supplyUsed += stats.supplyCost;
        return u;
      }
    }
  }
  return null;
}

function isFreeTile(world: World, x: number, y: number): boolean {
  const t = world.map.get(x, y);
  if (t === TILE.WATER || t === TILE.ROCK || t === TILE.GOLD_MINE || t === TILE.FOREST) return false;
  for (const e of world.entities.values()) {
    if (e.kind === "unit") {
      if (e.x === x && e.y === y) return false;
    } else if (e.kind === "building" && e.construction >= 1) {
      const fp = getBuildingStats(e.faction, e.buildingKind).footprint;
      if (x >= e.x && x < e.x + fp.w && y >= e.y && y < e.y + fp.h) return false;
    }
  }
  return true;
}

export function stepBuilding(world: World, b: BuildingEntity, dt: number): void {
  if (b.hp <= 0) {
    b.corpseTimer += dt;
    if (b.corpseTimer > 3) {
      // Free supply no longer used (units still have to die separately).
      world.players[b.faction].buildingsLost++;
      world.removeEntity(b.id);
      world.recomputeSupplyCap(b.faction);
    }
    return;
  }
  // Training queue: progress the head entry.
  if (b.trainQueue.length > 0) {
    const head = b.trainQueue[0] as { unit: import("./stats.js").UnitKind; progress: number; total: number };
    head.progress += dt;
    if (head.progress >= head.total) {
      const kind = head.unit;
      b.trainQueue.shift();
      const u = trySpawnUnitAtAdjacentTile(world, b, kind);
      if (u === null) {
        // C6: spawn failed. Push the head back as a retry on next tick? We
        // keep it simple: refund the supply, drop the entry (so we don't loop
        // forever). The test that exercises C6 will spawn at radius 1+.
        // Actually, we should retry until success: place back at progress=0.
        b.trainQueue.unshift({ unit: kind, progress: 0, total: head.total });
      }
    }
  }
}

export function stepProjectile(world: World, p: ProjectileEntity, dt: number): void {
  const target = world.entities.get(p.target);
  if (!target) {
    world.removeEntity(p.id);
    return;
  }
  const tx = target.kind === "unit" ? target.x : (target as BuildingEntity).x;
  const ty = target.kind === "unit" ? target.y : (target as BuildingEntity).y;
  // Target center approximation: tx+0.5, ty+0.5 for units; for buildings use the
  // center of footprint.
  const cx = target.kind === "unit" ? tx + HALF_TILE : tx;
  const cy = target.kind === "unit" ? ty + HALF_TILE : ty;
  const dx = cx - p.x;
  const dy = cy - p.y;
  const dist = Math.hypot(dx, dy);
  const step = p.speed * dt;
  if (dist <= step || dist < 0.1) {
    // Apply damage.
    if (target.kind === "unit") {
      const tu = target as UnitEntity;
      const armor = getUnitStats(tu.faction, tu.unitKind).armor;
      const actual = Math.max(1, p.damage - armor);
      tu.hp -= actual;
      if (tu.hp <= 0) {
        world.removeEntity(tu.id);
        world.players[tu.faction].unitsLost++;
        const stats = getUnitStats(tu.faction, tu.unitKind);
        world.players[tu.faction].supplyUsed = Math.max(0, world.players[tu.faction].supplyUsed - stats.supplyCost);
        // Track kills for the source.
        const src = world.entities.get(p.source);
        if (src && src.kind === "unit") {
          (src as UnitEntity).damageDealt += actual;
          world.players[(src as UnitEntity).faction].kills++;
        }
      }
    } else if (target.kind === "building") {
      const tb = target as BuildingEntity;
      const actual = Math.max(1, p.damage);
      tb.hp -= actual;
      if (tb.hp <= 0) {
        world.players[tb.faction].buildingsLost++;
        world.removeEntity(tb.id);
        world.recomputeSupplyCap(tb.faction);
        const src = world.entities.get(p.source);
        if (src && src.kind === "unit") {
          world.players[(src as UnitEntity).faction].kills++;
        }
      }
    }
    world.removeEntity(p.id);
    return;
  }
  p.x += (dx / dist) * step;
  p.y += (dy / dist) * step;
}

void findPath;
void octile;
void TICK_DT;
void isBuilding;
void isProjectile;
void isUnit;

// Unit step: advances a single unit by one tick. The unit's state lives in
// UnitOrderState (see orders.ts). This file dispatches to phase-specific
// helpers imported from the other step modules.

import { World } from "./world.js";
import { BuildingEntity, isBuilding, isUnit, UnitEntity } from "./entities.js";
import { TILE, isResourceTile, isWalkableTile } from "./tiles.js";
import { findPath, octile } from "./pathfinding.js";
import { getBuildingStats, getUnitStats, HARVEST } from "./stats.js";
import { Order } from "./orders.js";
import { buildTerrainBlockedMap, isAdjacent } from "./helpers.js";
import { SIM_CONSTANTS } from "./stats.js";

function tileFreeOfOtherUnits(world: World, x: number, y: number, selfId: number): boolean {
  for (const e of world.entities.values()) {
    if (e.kind !== "unit") continue;
    if (e.id === selfId) continue;
    if (e.x === x && e.y === y) return false;
  }
  return true;
}

export function unitBlocks(world: World, selfId: number): Uint8Array {
  const arr = buildTerrainBlockedMap(world);
  for (const e of world.entities.values()) {
    if (e.kind !== "unit") continue;
    if (e.id === selfId) continue;
    arr[e.y * world.map.width + e.x] = 1;
  }
  return arr;
}

export function nearestDropOffBuilding(
  world: World,
  unit: UnitEntity,
  resource: "gold" | "wood",
): BuildingEntity | null {
  let best: BuildingEntity | null = null;
  let bestD = Infinity;
  for (const e of world.entities.values()) {
    if (e.kind !== "building") continue;
    if (e.faction !== unit.faction) continue;
    if (e.construction < 1) continue;
    if (resource === "gold" && e.buildingKind !== "townhall") continue;
    if (resource === "wood" && e.buildingKind !== "townhall" && e.buildingKind !== "lumbermill") continue;
    const d = octile(unit.x, unit.y, e.x, e.y);
    if (d < bestD) {
      bestD = d;
      best = e;
    }
  }
  return best;
}

export function findWalkableTileAdjacentToSource(
  world: World,
  blocked: Uint8Array,
  sx: number, sy: number,
  selfId: number,
): { x: number; y: number } | null {
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue;
      const x = sx + dx;
      const y = sy + dy;
      if (x < 0 || y < 0 || x >= world.map.width || y >= world.map.height) continue;
      if (blocked[y * world.map.width + x] === 1) continue;
      if (!isWalkableTile(world.map.get(x, y))) continue;
      if (!tileFreeOfOtherUnits(world, x, y, selfId)) continue;
      return { x, y };
    }
  }
  return null;
}

export function findAdjacentWalkableToBuilding(
  world: World,
  blocked: Uint8Array,
  b: BuildingEntity,
  selfId: number,
): { x: number; y: number } | null {
  const stats = getBuildingStats(b.faction, b.buildingKind);
  const W = world.map.width;
  for (let dy = -1; dy <= stats.footprint.h; dy++) {
    for (let dx = -1; dx <= stats.footprint.w; dx++) {
      const onLeft = dx === -1;
      const onRight = dx === stats.footprint.w;
      const onTop = dy === -1;
      const onBottom = dy === stats.footprint.h;
      if (!onLeft && !onRight && !onTop && !onBottom) continue;
      const x = b.x + dx;
      const y = b.y + dy;
      if (x < 0 || y < 0 || x >= W || y >= world.map.height) continue;
      if (blocked[y * W + x] === 1) continue;
      if (!isWalkableTile(world.map.get(x, y))) continue;
      if (!tileFreeOfOtherUnits(world, x, y, selfId)) continue;
      return { x, y };
    }
  }
  return null;
}

export function retargetHarvestSource(
  world: World,
  unit: UnitEntity,
  resource: "gold" | "wood",
  blocked: Uint8Array,
): boolean {
  let best: { x: number; y: number; d: number } | null = null;
  for (let y = 0; y < world.map.height; y++) {
    for (let x = 0; x < world.map.width; x++) {
      const t = world.map.get(x, y);
      if (resource === "gold" && t !== TILE.GOLD_MINE) continue;
      if (resource === "wood" && t !== TILE.FOREST) continue;
      const idx = y * world.map.width + x;
      if (resource === "gold" && (world.map.mineGold[idx] ?? 0) <= 0) continue;
      if (resource === "wood" && (world.map.forestWood[idx] ?? 0) <= 0) continue;
      const d = octile(unit.x, unit.y, x, y);
      if (best === null || d < best.d) best = { x, y, d };
    }
  }
  if (best === null) return false;
  const adj = findWalkableTileAdjacentToSource(world, blocked, best.x, best.y, unit.id);
  if (adj === null) return false;
  const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
  if (path === null) return false;
  unit.orderState.order = { kind: "harvest", tx: best.x, ty: best.y } as Order;
  unit.orderState.path = path;
  unit.orderState.repathAttempts = 0;
  unit.orderState.phase = "gathering";
  return true;
}

export function stepAlongPath(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  if (unit.orderState.path.length === 0) return;
  const stats = getUnitStats(unit.faction, unit.unitKind);
  const speed = stats.moveSpeed;
  let progress = unit.orderState.moveProgress;
  let guard = 0;
  while (progress < dt * speed && guard++ < 8) {
    const next = unit.orderState.path[0];
    if (!next) break;
    const [nx, ny] = next;
    if (!isWalkableTile(world.map.get(nx, ny))) {
      unit.orderState.path = [];
      return;
    }
    const fromX = unit.x;
    const fromY = unit.y;
    if (nx !== fromX && ny !== fromY) {
      if (
        !isWalkableTile(world.map.get(fromX, ny)) ||
        !isWalkableTile(world.map.get(nx, fromY))
      ) {
        const axial = findAxialDetour(world, blocked, fromX, fromY, nx, ny, unit.id);
        if (axial !== null) {
          unit.orderState.path.unshift(axial);
          continue;
        }
        unit.orderState.path = [];
        return;
      }
    }
    if (!tileFreeOfOtherUnits(world, nx, ny, unit.id)) return;
    const remaining = dt * speed - progress;
    const dx = nx - fromX;
    const dy = ny - fromY;
    const stepCost = dx !== 0 && dy !== 0 ? Math.SQRT2 : 1;
    if (remaining >= stepCost) {
      unit.x = nx;
      unit.y = ny;
      unit.subX = 0.5;
      unit.subY = 0.5;
      progress += stepCost;
      unit.orderState.path.shift();
      const jx = (world.rng.next() - 0.5) * 0.1;
      const jy = (world.rng.next() - 0.5) * 0.1;
      unit.subX = Math.max(0.05, Math.min(0.95, 0.5 + jx));
      unit.subY = Math.max(0.05, Math.min(0.95, 0.5 + jy));
    } else {
      const frac = remaining / stepCost;
      unit.subX = 0.5 + (nx - fromX) * frac;
      unit.subY = 0.5 + (ny - fromY) * frac;
      progress = dt * speed;
    }
  }
  unit.orderState.moveProgress = progress;
  if (unit.orderState.path.length === 0) {
    unit.subX = 0.5;
    unit.subY = 0.5;
  }
}

function findAxialDetour(
  world: World,
  blocked: Uint8Array,
  fromX: number, fromY: number,
  toX: number, toY: number,
  selfId: number,
): [number, number] | null {
  const c1 = isWalkableTile(world.map.get(toX, fromY)) && tileFreeOfOtherUnits(world, toX, fromY, selfId);
  const c2 = isWalkableTile(world.map.get(fromX, toY)) && tileFreeOfOtherUnits(world, fromX, toY, selfId);
  if (c1 && blocked[fromY * world.map.width + toX] === 0) return [toX, fromY];
  if (c2 && blocked[toY * world.map.width + fromX] === 0) return [fromX, toY];
  return null;
}

void isUnit;
void isBuilding;
void isResourceTile;
void Order;

// Unit step orchestrator. Per-tick unit lifecycle: idle auto-acquire,
// combat, gather/return, build, repair, watchdog.

import { World } from "./world.js";
import { BuildingEntity, UnitEntity, isBuilding, isUnit } from "./entities.js";
import { TILE, isResourceTile } from "./tiles.js";
import { findPath, octile } from "./pathfinding.js";
import { getBuildingStats, getUnitStats, HARVEST } from "./stats.js";
import { Order } from "./orders.js";
import { isAdjacent } from "./helpers.js";
import { SIM_CONSTANTS } from "./stats.js";
import {
  unitBlocks,
  nearestDropOffBuilding,
  findWalkableTileAdjacentToSource,
  findAdjacentWalkableToBuilding,
  retargetHarvestSource,
  stepAlongPath,
} from "./unitMovement.js";

function autoAcquireTarget(world: World, unit: UnitEntity): void {
  const stats = getUnitStats(unit.faction, unit.unitKind);
  let best: { id: number; d: number } | null = null;
  for (const e of world.entities.values()) {
    if (e.faction === unit.faction) continue;
    if (e.kind !== "unit" && e.kind !== "building") continue;
    if (e.kind === "building" && e.construction < 1) continue;
    const tx = e.kind === "unit" ? e.x : (e as BuildingEntity).x;
    const ty = e.kind === "unit" ? e.y : (e as BuildingEntity).y;
    const d = octile(unit.x, unit.y, tx, ty);
    if (d > stats.sightRadius) continue;
    if (best === null || d < best.d) best = { id: e.id, d };
  }
  unit.target = best ? best.id : null;
}

function tryAttack(world: World, unit: UnitEntity, target: number): void {
  const t = world.entities.get(target);
  if (!t) {
    unit.target = null;
    return;
  }
  const dmg = getUnitStats(unit.faction, unit.unitKind).damage;
  if (t.kind === "unit") {
    const armor = getUnitStats(t.faction, t.unitKind).armor;
    const actual = Math.max(1, dmg - armor);
    t.hp -= actual;
    unit.damageDealt += actual;
    if (t.hp <= 0) {
      world.removeEntity(t.id);
      world.players[t.faction].unitsLost++;
      world.players[unit.faction].kills++;
      const stats = getUnitStats(t.faction, t.unitKind);
      world.players[t.faction].supplyUsed = Math.max(0, world.players[t.faction].supplyUsed - stats.supplyCost);
    }
  } else if (t.kind === "building") {
    const actual = Math.max(1, dmg);
    (t as BuildingEntity).hp -= actual;
    unit.damageDealt += actual;
    if ((t as BuildingEntity).hp <= 0) {
      destroyBuilding(world, t as BuildingEntity);
    }
  } else {
    unit.target = null;
  }
}

function destroyBuilding(world: World, b: BuildingEntity): void {
  const p = world.players[b.faction];
  p.buildingsLost++;
  world.removeEntity(b.id);
  world.recomputeSupplyCap(b.faction);
}

function stepGather(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  const order = unit.orderState.order as { kind: "harvest"; tx: number; ty: number } | null;
  if (!order) {
    unit.orderState.phase = "idle";
    return;
  }
  if (unit.orderState.path.length > 0) {
    stepAlongPath(world, unit, blocked, dt);
    return;
  }
  if (!isAdjacent(unit.x, unit.y, order.tx, order.ty)) {
    const adj = findWalkableTileAdjacentToSource(world, blocked, order.tx, order.ty, unit.id);
    if (adj === null) {
      unit.orderState.phase = "idle";
      return;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      unit.orderState.phase = "idle";
      return;
    }
    unit.orderState.path = path;
    return;
  }
  const t = world.map.get(order.tx, order.ty);
  if (t === TILE.GOLD_MINE) {
    const idx = order.ty * world.map.width + order.tx;
    if ((world.map.mineGold[idx] ?? 0) <= 0) {
      if (!retargetHarvestSource(world, unit, "gold", blocked)) {
        if (unit.orderState.cargo.gold > 0) {
          returnFromHarvest(world, unit, blocked, "gold");
        } else {
          unit.orderState.phase = "idle";
        }
      }
      return;
    }
    unit.orderState.workProgress += dt;
    if (unit.orderState.workProgress >= HARVEST.goldGatherTime) {
      unit.orderState.workProgress = 0;
      const carry = Math.min(HARVEST.goldPerTrip, world.map.mineGold[idx] ?? 0);
      world.map.mineGold[idx] = Math.max(0, (world.map.mineGold[idx] ?? 0) - carry);
      unit.orderState.cargo.gold += carry;
      if ((world.map.mineGold[idx] ?? 0) <= 0) {
        world.map.set(order.tx, order.ty, TILE.DEPLETED_MINE);
      }
      returnFromHarvest(world, unit, blocked, "gold");
    }
  } else if (t === TILE.FOREST) {
    const idx = order.ty * world.map.width + order.tx;
    if ((world.map.forestWood[idx] ?? 0) <= 0) {
      if (!retargetHarvestSource(world, unit, "wood", blocked)) {
        if (unit.orderState.cargo.wood > 0) {
          returnFromHarvest(world, unit, blocked, "wood");
        } else {
          unit.orderState.phase = "idle";
        }
      }
      return;
    }
    unit.orderState.workProgress += dt;
    if (unit.orderState.workProgress >= HARVEST.woodChopTime) {
      unit.orderState.workProgress = 0;
      const carry = Math.min(HARVEST.woodPerTrip, world.map.forestWood[idx] ?? 0);
      world.map.forestWood[idx] = Math.max(0, (world.map.forestWood[idx] ?? 0) - carry);
      unit.orderState.cargo.wood += carry;
      if ((world.map.forestWood[idx] ?? 0) <= 0) {
        world.map.set(order.tx, order.ty, TILE.STUMP);
      }
      returnFromHarvest(world, unit, blocked, "wood");
    }
  } else {
    unit.orderState.phase = "idle";
  }
}

function returnFromHarvest(
  world: World,
  unit: UnitEntity,
  blocked: Uint8Array,
  resource: "gold" | "wood",
): void {
  const drop = nearestDropOffBuilding(world, unit, resource);
  if (!drop) {
    unit.orderState.phase = "idle";
    return;
  }
  const adj = findAdjacentWalkableToBuilding(world, blocked, drop, unit.id);
  if (adj === null) {
    unit.orderState.phase = "idle";
    return;
  }
  const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
  if (path === null) {
    unit.orderState.phase = "idle";
    return;
  }
  unit.orderState.path = path;
  unit.orderState.phase = "returning";
}

function stepReturn(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  if (unit.orderState.path.length > 0) {
    stepAlongPath(world, unit, blocked, dt);
    return;
  }
  const order = unit.orderState.order as { kind: "harvest"; tx: number; ty: number } | null;
  const resource: "gold" | "wood" = order && world.map.get(order.tx, order.ty) === TILE.FOREST ? "wood" : "gold";
  const drop = nearestDropOffBuilding(world, unit, resource);
  if (!drop) {
    unit.orderState.phase = "idle";
    return;
  }
  if (!isAdjacent(unit.x, unit.y, drop.x, drop.y)) {
    const adj = findAdjacentWalkableToBuilding(world, blocked, drop, unit.id);
    if (adj === null) {
      unit.orderState.phase = "idle";
      return;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      unit.orderState.phase = "idle";
      return;
    }
    unit.orderState.path = path;
    return;
  }
  if (resource === "gold") {
    world.players[unit.faction].gold += unit.orderState.cargo.gold;
    unit.orderState.cargo.gold = 0;
  } else {
    world.players[unit.faction].wood += unit.orderState.cargo.wood;
    unit.orderState.cargo.wood = 0;
  }
  if (!retargetHarvestSource(world, unit, resource, blocked)) {
    unit.orderState.phase = "idle";
  }
}

function stepBuild(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  if (unit.orderState.path.length > 0) {
    stepAlongPath(world, unit, blocked, dt);
    return;
  }
  const order = unit.orderState.order as { kind: "build"; building: import("./stats.js").BuildingKind; x: number; y: number } | null;
  if (!order) {
    unit.orderState.phase = "idle";
    return;
  }
  let build: BuildingEntity | null = null;
  for (const e of world.entities.values()) {
    if (e.kind !== "building") continue;
    if (e.faction !== unit.faction) continue;
    if (e.buildingKind !== order.building) continue;
    if (e.x === order.x && e.y === order.y) {
      build = e as BuildingEntity;
      break;
    }
  }
  if (!build) {
    unit.orderState.phase = "idle";
    return;
  }
  if (!isAdjacent(unit.x, unit.y, build.x, build.y)) {
    const adj = findAdjacentWalkableToBuilding(world, blocked, build, unit.id);
    if (adj === null) {
      unit.orderState.phase = "idle";
      return;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      unit.orderState.phase = "idle";
      return;
    }
    unit.orderState.path = path;
    return;
  }
  const stats = getBuildingStats(unit.faction, order.building);
  unit.orderState.workProgress += dt;
  const rate = 1 / Math.max(0.1, stats.buildTime);
  build.construction = Math.min(1, build.construction + rate * dt);
  if (build.construction >= 1) {
    build.builtBy = null;
    unit.orderState.phase = "idle";
    unit.orderState.order = null;
    world.recomputeSupplyCap(unit.faction);
  }
}

function stepRepair(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  if (unit.orderState.path.length > 0) {
    stepAlongPath(world, unit, blocked, dt);
    return;
  }
  const t = world.entities.get(unit.target ?? -1);
  if (!t || t.kind !== "building" || t.faction !== unit.faction) {
    unit.orderState.phase = "idle";
    return;
  }
  const b = t as BuildingEntity;
  if (b.hp >= b.maxHp) {
    unit.orderState.phase = "idle";
    return;
  }
  if (!isAdjacent(unit.x, unit.y, b.x, b.y)) {
    const adj = findAdjacentWalkableToBuilding(world, blocked, b, unit.id);
    if (adj === null) {
      unit.orderState.phase = "idle";
      return;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      unit.orderState.phase = "idle";
      return;
    }
    unit.orderState.path = path;
    return;
  }
  const cost = HARVEST.repairGoldPerSec * dt;
  if (world.players[unit.faction].gold < cost) return;
  world.players[unit.faction].gold -= cost;
  b.hp = Math.min(b.maxHp, b.hp + HARVEST.repairRate * dt);
  if (b.hp >= b.maxHp) {
    unit.orderState.phase = "idle";
    unit.orderState.order = null;
  }
}

function stepCombat(world: World, unit: UnitEntity, blocked: Uint8Array, dt: number): void {
  const stats = getUnitStats(unit.faction, unit.unitKind);
  if (unit.target === null || !world.entities.has(unit.target)) {
    autoAcquireTarget(world, unit);
  }
  if (unit.orderState.path.length > 0) {
    stepAlongPath(world, unit, blocked, dt);
  }
  if (unit.target !== null) {
    const t = world.entities.get(unit.target);
    if (!t) {
      unit.target = null;
      return;
    }
    const tx = t.kind === "unit" ? t.x : (t as BuildingEntity).x;
    const ty = t.kind === "unit" ? t.y : (t as BuildingEntity).y;
    const d = octile(unit.x, unit.y, tx, ty);
    if (d <= stats.attackRange) {
      unit.orderState.attackCooldown -= dt;
      if (unit.orderState.attackCooldown <= 0) {
        if (stats.attackProjectile) {
          world.spawnProjectile(unit.faction, unit.id, t.id, unit.x + 0.5, unit.y + 0.5, 8, stats.damage);
        } else {
          tryAttack(world, unit, t.id);
        }
        unit.orderState.attackCooldown = stats.attackCooldown;
      }
    } else {
      if (unit.orderState.path.length === 0) {
        const path = findPath(world.map, unit.x, unit.y, tx, ty, { blocked });
        if (path !== null) unit.orderState.path = path;
      }
    }
  }
}

/** Public: step one unit one tick. */
export function stepUnit(world: World, unit: UnitEntity, dt: number): void {
  if (unit.orderState.attackCooldown > 0) unit.orderState.attackCooldown -= dt;
  if (unit.hp <= 0) {
    unit.corpseTimer += dt;
    if (unit.corpseTimer > 3) {
      const stats = getUnitStats(unit.faction, unit.unitKind);
      world.players[unit.faction].supplyUsed = Math.max(0, world.players[unit.faction].supplyUsed - stats.supplyCost);
      world.removeEntity(unit.id);
    }
    return;
  }
  const blocked = unitBlocks(world, unit.id);
  const prev = {
    tx: unit.x,
    ty: unit.y,
    phase: unit.orderState.phase,
    cargoKey: `${unit.orderState.cargo.gold},${unit.orderState.cargo.wood}`,
  };
  switch (unit.orderState.phase) {
    case "moving":
    case "patrolling":
      stepAlongPath(world, unit, blocked, dt);
      if (unit.orderState.phase === "patrolling") {
        if (unit.target === null) autoAcquireTarget(world, unit);
        if (unit.target !== null) unit.orderState.phase = "attacking";
      }
      break;
    case "gathering":
      stepGather(world, unit, blocked, dt);
      break;
    case "returning":
      stepReturn(world, unit, blocked, dt);
      break;
    case "building":
      stepBuild(world, unit, blocked, dt);
      break;
    case "repairing":
      stepRepair(world, unit, blocked, dt);
      break;
    case "attacking":
      stepCombat(world, unit, blocked, dt);
      break;
    case "idle":
    default:
      if (unit.target === null) autoAcquireTarget(world, unit);
      if (unit.target !== null) unit.orderState.phase = "attacking";
      break;
  }
  if (unit.orderState.order !== null || unit.orderState.phase !== "idle") {
    unit.orderState.watchdog++;
  } else {
    unit.orderState.watchdog = 0;
  }
  if (unit.orderState.watchdog > 0) {
    const next = {
      tx: unit.x,
      ty: unit.y,
      phase: unit.orderState.phase,
      cargoKey: `${unit.orderState.cargo.gold},${unit.orderState.cargo.wood}`,
    };
    const progressed =
      next.tx !== prev.tx ||
      next.ty !== prev.ty ||
      next.phase !== prev.phase ||
      next.cargoKey !== prev.cargoKey;
    if (progressed) {
      unit.orderState.watchdog = 0;
      unit.orderState.lastSnapshot = next;
    } else if (unit.orderState.watchdog > SIM_CONSTANTS.progressWatchdogTicks) {
      unit.orderState.phase = "idle";
      unit.orderState.order = null;
      unit.orderState.watchdog = 0;
    }
  }
}

void isUnit;
void isBuilding;
void isResourceTile;
void Order;

// Sim step: top-level world tick driver. Advances all units, buildings, and
// projectiles one tick; recomputes fog of war; resolves win/lose.

import { World } from "./world.js";
import { BuildingEntity, ProjectileEntity, UnitEntity, isBuilding, isProjectile, isUnit } from "./entities.js";
import { TILE } from "./tiles.js";
import { TICK_DT } from "./stats.js";
import { stepUnit } from "./unitStep.js";
import { stepBuilding, stepProjectile } from "./buildingStep.js";
import { FOG, FOG as FOG_CONST } from "./fog.js";
import { getUnitStats } from "./stats.js";

function recomputeFog(world: World): void {
  // Reset all to UNEXPLORED.
  for (const f of ["humans", "orcs"] as const) {
    const grid = world.fog.get(f);
    grid.fill(FOG_CONST.UNEXPLORED);
  }
  // For each unit/building of a faction, reveal a sight-radius disk in that
  // faction's fog.
  for (const faction of ["humans", "orcs"] as const) {
    const grid = world.fog.get(faction);
    for (const e of world.entities.values()) {
      if (e.faction !== faction) continue;
      if (e.kind === "projectile") continue;
      let radius = 0;
      if (e.kind === "unit") {
        radius = getUnitStats(e.faction, e.unitKind).sightRadius;
      } else {
        // Use building's sight radius (or default).
        radius = e.buildingKind === "townhall" ? 9 : e.buildingKind === "guardtower" ? 8 : 6;
      }
      const cx = e.x;
      const cy = e.y;
      const r = Math.ceil(radius);
      for (let dy = -r; dy <= r; dy++) {
        for (let dx = -r; dx <= r; dx++) {
          const x = cx + dx;
          const y = cy + dy;
          if (!world.map.inBounds(x, y)) continue;
          if (dx * dx + dy * dy > radius * radius) continue;
          grid[y * world.map.width + x] = FOG_CONST.VISIBLE;
        }
      }
    }
  }
  // Demote VISIBLE tiles to EXPLORED where they are not in line of sight.
  // For simplicity, we use the per-tile chebyshev distance to nearest sight
  // source of the same faction. (Revealed = VISIBLE; other previously-revealed
  // tiles stay EXPLORED.) This is approximate but cheap and good enough.
  for (const faction of ["humans", "orcs"] as const) {
    const grid = world.fog.get(faction);
    for (let i = 0; i < grid.length; i++) {
      if (grid[i] === FOG_CONST.UNEXPLORED) {
        // Check whether the tile was ever seen (i.e. was VISIBLE before reset).
        // We don't have a "last seen" buffer; the explored state is implicit in
        // the map tiles which never change after generation. So we just leave
        // UNEXPLORED as UNEXPLORED. This is a deliberate simplification: the
        // renderer can still see terrain/buildings of self by default.
        continue;
      }
    }
  }
}

function checkOutcome(world: World): void {
  if (world.outcome !== "playing") return;
  const humansAlive = world.buildingsOf("humans").some((b) => b.hp > 0);
  const orcsAlive = world.buildingsOf("orcs").some((b) => b.hp > 0);
  if (!humansAlive && !orcsAlive) {
    world.outcome = "defeat";
    world.winner = null;
  } else if (!humansAlive) {
    world.outcome = "victory";
    world.winner = "orcs";
  } else if (!orcsAlive) {
    world.outcome = "victory";
    world.winner = "humans";
  }
}

/** Step the world one sim-tick. dt defaults to TICK_DT. */
export function step(world: World, dt: number = TICK_DT): void {
  if (world.paused) return;
  // Snapshot entity ids so iteration is stable if we add/remove.
  const ids: number[] = [];
  for (const id of world.entities.keys()) ids.push(id);
  // Step projectiles first (resolve earlier hits).
  for (const id of ids) {
    const e = world.entities.get(id);
    if (!e) continue;
    if (e.kind === "projectile") stepProjectile(world, e, dt);
  }
  // Step units.
  for (const id of ids) {
    const e = world.entities.get(id);
    if (!e) continue;
    if (e.kind === "unit") stepUnit(world, e, dt);
  }
  // Step buildings.
  for (const id of ids) {
    const e = world.entities.get(id);
    if (!e) continue;
    if (e.kind === "building") stepBuilding(world, e, dt);
  }
  // Recompute supply caps (in case buildings finished).
  world.recomputeSupplyCap("humans");
  world.recomputeSupplyCap("orcs");
  // Recompute fog.
  recomputeFog(world);
  // Check outcome.
  checkOutcome(world);
  // Advance tick.
  world.tick++;
}

void FOG;
void TILE;
void isBuilding;
void isProjectile;
void isUnit;
void BuildingEntity;
void ProjectileEntity;
void UnitEntity;

