// Order handler: the per-unit state machine that consumes an issued Order
// and produces observable progress. The unit's state is in
// UnitOrderState; this module is a pure function of (world, unit, dt) that
// advances it.

import { World } from "./world.js";
import { BuildingEntity, UnitEntity, isBuilding, isUnit } from "./entities.js";
import {
  AttackMoveOrder,
  AttackOrder,
  BuildOrder,
  HarvestOrder,
  MoveOrder,
  Order,
  OrderPhase,
  RepairOrder,
  TrainOrder,
} from "./orders.js";
import { findPath, octile } from "./pathfinding.js";
import { getBuildingStats, getUnitStats, HARVEST, TICK_DT, SIM_CONSTANTS } from "./stats.js";
import { TILE, isResourceTile, isWalkableTile } from "./tiles.js";
import { buildTerrainBlockedMap, isAdjacent, pathStepTowards, pickAdjacentWalkable } from "./helpers.js";

const ORDER_RETRY_LIMIT = 3;

function unitBlocksForWorld(world: World, selfId: number): Uint8Array {
  // Base: terrain + buildings.
  const blocked = buildTerrainBlockedMap(world);
  // Add other units' tiles as blocked.
  for (const e of world.entities.values()) {
    if (e.kind !== "unit") continue;
    if (e.id === selfId) continue;
    blocked[e.y * world.map.width + e.x] = 1;
  }
  return blocked;
}

function nearestDropOff(
  world: World,
  unit: UnitEntity,
  resource: "gold" | "wood",
): BuildingEntity | null {
  let best: BuildingEntity | null = null;
  let bestD = Infinity;
  for (const e of world.entities.values()) {
    if (e.kind !== "building") continue;
    if (e.faction !== unit.faction) continue;
    if (e.construction < 1) continue;
    if (resource === "gold" && e.buildingKind !== "townhall") continue;
    if (resource === "wood" && e.buildingKind !== "townhall" && e.buildingKind !== "lumbermill") continue;
    const d = octile(unit.x, unit.y, e.x + 0, e.y + 0);
    if (d < bestD) {
      bestD = d;
      best = e;
    }
  }
  return best;
}

function nearestSource(
  world: World,
  unit: UnitEntity,
  resource: "gold" | "wood",
  exclude: ReadonlySet<number>,
): { x: number; y: number } | null {
  let best: { x: number; y: number; d: number } | null = null;
  for (let y = 0; y < world.map.height; y++) {
    for (let x = 0; x < world.map.width; x++) {
      const t = world.map.get(x, y);
      if (resource === "gold" && t !== TILE.GOLD_MINE) continue;
      if (resource === "wood" && t !== TILE.FOREST) continue;
      const key = y * world.map.width + x;
      if (exclude.has(key)) continue;
      if (resource === "gold" && (world.map.mineGold[key] ?? 0) <= 0) continue;
      if (resource === "wood" && (world.map.forestWood[key] ?? 0) <= 0) continue;
      const d = octile(unit.x, unit.y, x, y);
      if (best === null || d < best.d) best = { x, y, d };
    }
  }
  return best;
}

function nearestEmptyWalkableAdjacentToSource(
  world: World,
  sourceX: number,
  sourceY: number,
  blocked: Uint8Array,
  selfId: number,
): { x: number; y: number } | null {
  const w = world.map.width;
  let best: { x: number; y: number; d: number } | null = null;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue;
      const x = sourceX + dx;
      const y = sourceY + dy;
      if (x < 0 || y < 0 || x >= world.map.width || y >= world.map.height) continue;
      if (blocked[y * w + x] === 1) continue;
      if (!isWalkableTile(world.map.get(x, y))) continue;
      // Must also be free of other units.
      let occupied = false;
      for (const e of world.entities.values()) {
        if (e.kind !== "unit") continue;
        if (e.id === selfId) continue;
        if (e.x === x && e.y === y) {
          occupied = true;
          break;
        }
      }
      if (occupied) continue;
      const d = dx * dx + dy * dy;
      if (best === null || d < best.d) best = { x, y, d };
    }
  }
  return best;
}

function trySetOrder(
  world: World,
  unit: UnitEntity,
  order: Order,
  blocked: Uint8Array,
): boolean {
  unit.orderState.order = order;
  unit.orderState.path = [];
  unit.orderState.moveProgress = 0;
  unit.orderState.workProgress = 0;
  unit.orderState.repathAttempts = 0;
  unit.orderState.cargo = { gold: 0, wood: 0 };
  unit.orderState.watchdog = 0;
  unit.target = null;
  unit.moveGoal = null;

  if (order.kind === "move" || order.kind === "attackMove") {
    const goal = order as MoveOrder | AttackMoveOrder;
    const path = findPath(world.map, unit.x, unit.y, goal.x, goal.y, { blocked });
    if (path === null) {
      // C4: try the nearest reachable point via BFS.
      const near = nearestReachableTile(world, blocked, unit.x, unit.y, goal.x, goal.y);
      if (near === null) {
        // Truly unreachable — go idle.
        unit.orderState.order = null;
        unit.orderState.phase = "idle";
        return false;
      }
      const path2 = findPath(world.map, unit.x, unit.y, near.x, near.y, { blocked });
      if (path2 === null) {
        unit.orderState.order = null;
        unit.orderState.phase = "idle";
        return false;
      }
      unit.orderState.path = path2;
      unit.orderState.phase = order.kind === "attackMove" ? "patrolling" : "moving";
    } else {
      unit.orderState.path = path;
      unit.orderState.phase = order.kind === "attackMove" ? "patrolling" : "moving";
    }
  } else if (order.kind === "attack") {
    const target = world.entities.get((order as AttackOrder).target);
    if (!target || (target.kind !== "unit" && target.kind !== "building") || target.faction === unit.faction) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    unit.target = target.id;
    unit.orderState.phase = "attacking";
  } else if (order.kind === "harvest") {
    const h = order as HarvestOrder;
    const t = world.map.get(h.tx, h.ty);
    if (!isResourceTile(t)) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    // Set phase to "moving" — the unit walks to an adjacent walkable tile.
    const adj = pickAdjacentWalkable(world, h.tx, h.ty, blocked);
    if (adj === null) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    unit.orderState.path = path;
    unit.orderState.phase = "gathering";
  } else if (order.kind === "build") {
    const b = order as BuildOrder;
    const stats = getBuildingStats(unit.faction, b.building);
    // Verify placement.
    if (!isBuildableAt(world, b.x, b.y, stats.footprint.w, stats.footprint.h, unit.faction, unit.id)) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    // Pay cost.
    if (!canPay(world, unit.faction, stats.goldCost, stats.woodCost)) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    pay(world, unit.faction, stats.goldCost, stats.woodCost);
    const build = world.spawnBuilding(unit.faction, b.building, b.x, b.y, 0, unit.id);
    build.trainQueue = [];
    // Reserve a path: unit walks adjacent and builds.
    const adj = findAdjacentWalkableToFootprint(world, blocked, b.x, b.y, stats.footprint.w, stats.footprint.h);
    if (adj === null) {
      world.removeEntity(build.id);
      refund(world, unit.faction, stats.goldCost, stats.woodCost);
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    const path = findPath(world.map, unit.x, unit.y, adj.x, adj.y, { blocked });
    if (path === null) {
      world.removeEntity(build.id);
      refund(world, unit.faction, stats.goldCost, stats.woodCost);
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    unit.orderState.path = path;
    unit.orderState.phase = "building";
  } else if (order.kind === "repair") {
    const r = order as RepairOrder;
    const target = world.entities.get(r.target);
    if (!target || !isBuilding(target) || target.faction !== unit.faction) {
      unit.orderState.order = null;
      unit.orderState.phase = "idle";
      return false;
    }
    unit.target = target.id;
    unit.orderState.phase = "repairing";
  } else if (order.kind === "train") {
    // Train orders are consumed at the building level, not the unit level.
    unit.orderState.order = null;
    unit.orderState.phase = "idle";
    return false;
  }
  return true;
}

function isBuildableAt(
  world: World,
  x: number,
  y: number,
  w: number,
  h: number,
  faction: string,
  workerId: number,
): boolean {
  const map = world.map;
  for (let dy = 0; dy < h; dy++) {
    for (let dx = 0; dx < w; dx++) {
      const xx = x + dx;
      const yy = y + dy;
      if (!map.inBounds(xx, yy)) return false;
      if (!isWalkableTile(map.get(xx, yy))) return false;
      if (isResourceTile(map.get(xx, yy))) return false;
    }
  }
  // No overlap with existing buildings.
  for (const e of world.entities.values()) {
    if (e.kind !== "building") continue;
    if (e.construction < 1) continue;
    const stats = getBuildingStats(e.faction, e.buildingKind);
    if (rectsOverlap(x, y, w, h, e.x, e.y, stats.footprint.w, stats.footprint.h)) return false;
  }
  // No unit on the footprint (except the building worker itself).
  for (const e of world.entities.values()) {
    if (e.kind !== "unit") continue;
    if (e.id === workerId) continue;
    if (e.x >= x && e.x < x + w && e.y >= y && e.y < y + h) return false;
  }
  void faction;
  return true;
}

function rectsOverlap(
  ax: number, ay: number, aw: number, ah: number,
  bx: number, by: number, bw: number, bh: number,
): boolean {
  return ax < bx + bw && ax + aw > bx && ay < by + bh && ay + ah > by;
}

function findAdjacentWalkableToFootprint(
  world: World,
  blocked: Uint8Array,
  x: number, y: number, w: number, h: number,
): { x: number; y: number } | null {
  const W = world.map.width;
  const H = world.map.height;
  for (let dy = -1; dy <= h; dy++) {
    for (let dx = -1; dx <= w; dx++) {
      // perimeter only
      const onLeft = dx === -1;
      const onRight = dx === w;
      const onTop = dy === -1;
      const onBottom = dy === h;
      if (!onLeft && !onRight && !onTop && !onBottom) continue;
      const px = x + dx;
      const py = y + dy;
      if (px < 0 || py < 0 || px >= W || py >= H) continue;
      if (blocked[py * W + px] === 1) continue;
      if (!isWalkableTile(world.map.get(px, py))) continue;
      return { x: px, y: py };
    }
  }
  return null;
}

function nearestReachableTile(
  world: World,
  blocked: Uint8Array,
  sx: number, sy: number, gx: number, gy: number,
): { x: number; y: number } | null {
  // BFS outward from gx,gy up to a bounded radius, return first reachable.
  const W = world.map.width;
  const H = world.map.height;
  const visited = new Uint8Array(W * H);
  const queue: Array<[number, number]> = [[gx, gy]];
  let head = 0;
  let safety = 200;
  while (head < queue.length && safety-- > 0) {
    const [x, y] = queue[head++] as [number, number];
    if (x < 0 || y < 0 || x >= W || y >= H) continue;
    if (visited[y * W + x] === 1) continue;
    visited[y * W + x] = 1;
    if (blocked[y * W + x] === 0 && isWalkableTile(world.map.get(x, y))) {
      // Try to path to it.
      const path = findPath(world.map, sx, sy, x, y, { blocked });
      if (path !== null) return { x, y };
    }
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx;
        const ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue;
        if (visited[ny * W + nx] === 1) continue;
        queue.push([nx, ny]);
      }
    }
  }
  return null;
}

function canPay(world: World, faction: "humans" | "orcs", gold: number, wood: number): boolean {
  const p = world.players[faction];
  return p.gold >= gold && p.wood >= wood;
}

function pay(world: World, faction: "humans" | "orcs", gold: number, wood: number): void {
  const p = world.players[faction];
  p.gold -= gold;
  p.wood -= wood;
}

function refund(world: World, faction: "humans" | "orcs", gold: number, wood: number): void {
  const p = world.players[faction];
  p.gold += gold;
  p.wood += wood;
}

/** Public: issue an order to a single unit. Returns true if the order was
 *  accepted (i.e. entered a non-idle phase). */
export function issueOrder(world: World, unitId: number, order: Order): boolean {
  const unit = world.entities.get(unitId);
  if (!unit || !isUnit(unit)) return false;
  const blocked = unitBlocksForWorld(world, unit.id);
  return trySetOrder(world, unit, order, blocked);
}

void TICK_DT;
void SIM_CONSTANTS;
void AttackMoveOrder;
void BuildOrder;
void HarvestOrder;
void MoveOrder;
void RepairOrder;
void TrainOrder;
void Order;
void OrderPhase;
void UnitOrderState;
void ORDER_RETRY_LIMIT;

