// Quick smoke test to ensure the simulation core wires up correctly.

import { describe, it, expect } from "vitest";
import { setupLevel } from "../src/sim/campaign.js";
import { step } from "../src/sim/sim.js";
import { World } from "../src/sim/world.js";
import { issueOrder } from "../src/sim/orderHandler.js";
import { TILE } from "../src/sim/tiles.js";

describe("smoke", () => {
  it("generates a playable level 1", () => {
    const info = setupLevel(1234, 1);
    expect(info.size).toBe(32);
    expect(info.result.starts.a.x).toBeGreaterThan(0);
    expect(info.result.starts.a.y).toBeGreaterThan(0);
    expect(info.map.width).toBe(32);
    expect(info.map.height).toBe(32);
  });

  it("a world with no entities steps without crashing", () => {
    const info = setupLevel(1234, 1);
    const w = new World(info.map, info.result.starts.a.x === 0 ? null as never : (require("../src/sim/rng.js") as { makeRng: (n: number) => import("../src/sim/rng.js").Rng }).makeRng(0));
    void w;
    expect(true).toBe(true);
  });

  it("place a worker, step 10 ticks, no crash", () => {
    const info = setupLevel(1234, 1);
    const { makeRng } = require("../src/sim/rng.js") as { makeRng: (n: number) => import("../src/sim/rng.js").Rng };
    const w = new World(info.map, makeRng(0));
    const u = w.spawnUnit("humans", "worker", info.result.starts.a.x, info.result.starts.a.y);
    expect(u).toBeDefined();
    for (let i = 0; i < 10; i++) step(w);
    expect(w.tick).toBe(10);
  });

  it("move a worker one tile", () => {
    const info = setupLevel(1234, 1);
    const { makeRng } = require("../src/sim/rng.js") as { makeRng: (n: number) => import("../src/sim/rng.js").Rng };
    const w = new World(info.map, makeRng(0));
    const u = w.spawnUnit("humans", "worker", info.result.starts.a.x, info.result.starts.a.y);
    // Find a walkable neighbor
    let target: { x: number; y: number } | null = null;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const x = u.x + dx;
        const y = u.y + dy;
        if (info.map.inBounds(x, y) && info.map.get(x, y) !== TILE.WATER && info.map.get(x, y) !== TILE.ROCK) {
          target = { x, y };
          break;
        }
      }
      if (target) break;
    }
    if (target) {
      const ok = issueOrder(w, u.id, { kind: "move", x: target.x, y: target.y });
      expect(ok).toBe(true);
    }
  });
});

