import { describe, it, expect } from "vitest";
import { setupLevel } from "../src/sim/campaign.js";
import { step } from "../src/sim/sim.js";
import { World } from "../src/sim/world.js";
import { issueOrder } from "../src/sim/orderHandler.js";
import { TILE, isWalkableTile } from "../src/sim/tiles.js";
import { makeRng } from "../src/sim/rng.js";

describe("smoke", () => {
  it("move a worker one tile", () => {
    const info = setupLevel(1234, 1);
    const w = new World(info.result.map, makeRng(0));
    const sx = info.result.starts.a.x;
    const sy = info.result.starts.a.y;
    console.log("start tile type:", info.result.map.get(sx, sy), "walkable:", isWalkableTile(info.result.map.get(sx, sy)));
    const u = w.spawnUnit("humans", "worker", sx, sy);
    let target: { x: number; y: number } | null = null;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const x = u.x + dx;
        const y = u.y + dy;
        if (info.result.map.inBounds(x, y)) {
          const t = info.result.map.get(x, y);
          console.log("candidate", x, y, "tile", t, "walkable", isWalkableTile(t));
          if (isWalkableTile(t)) {
            target = { x, y };
            break;
          }
        }
      }
      if (target) break;
    }
    expect(target).not.toBeNull();
    const ok = issueOrder(w, u.id, { kind: "move", x: target!.x, y: target!.y });
    expect(ok).toBe(true);
  });
});

