/** Find two start locations that satisfy C1. */
function findStarts(map: GameMap, rng: Rng): StartPair | null {
  const w = map.width;
  const h = map.height;
  const minSep = START_SEPARATION_RATIO * Math.max(w, h);
  const minLin = START_LINEAR_RATIO * Math.max(w, h);
  const patches: Array<{ center: { x: number; y: number }; tiles: Uint8Array; size: number }> = [];
  const seen = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      if (seen[i] === 1) continue;
      if (!isWalkableTile(map.get(x, y))) {
        seen[i] = 1;
        continue;
      }
      const flood = floodWalkable(map, x, y);
      for (let j = 0; j < flood.tiles.length; j++) {
        if (flood.tiles[j] === 1) seen[j] = 1;
      }
      if (flood.size < MIN_BUILDABLE * MIN_BUILDABLE) continue;
      let sx = 0;
      let sy = 0;
      let count = 0;
      for (let yy = 0; yy < h; yy++) {
        for (let xx = 0; xx < w; xx++) {
          if (flood.tiles[yy * w + xx] === 1) {
            sx += xx;
            sy += yy;
            count++;
          }
        }
      }
      // Snap centroid to nearest walkable tile in the patch.
      const cx = Math.round(sx / count);
      const cy = Math.round(sy / count);
      const snapped = snapToWalkable(map, flood.tiles, cx, cy);
      patches.push({
        center: snapped,
        tiles: flood.tiles,
        size: flood.size,
      });
    }
  }
  if (patches.length < 2) return null;
  patches.sort((a, b) => {
    if (a.size !== b.size) return b.size - a.size;
    return rng.next() - 0.5;
  });
  for (let i = 0; i < Math.min(8, patches.length); i++) {
    for (let j = i + 1; j < Math.min(16, patches.length); j++) {
      const a = patches[i] as { center: { x: number; y: number } };
      const b = patches[j] as { center: { x: number; y: number } };
      const linear = octile(a.center.x, a.center.y, b.center.x, b.center.y);
      if (linear < minLin) continue;
      const land = landPathLength(map, a.center.x, a.center.y, b.center.x, b.center.y);
      if (land < minSep) continue;
      return { a: a.center, b: b.center };
    }
  }
  return null;
}

function snapToWalkable(map: GameMap, tiles: Uint8Array, cx: number, cy: number): { x: number; y: number } {
  if (map.inBounds(cx, cy) && tiles[cy * map.width + cx] === 1 && isWalkableTile(map.get(cx, cy))) {
    return { x: cx, y: cy };
  }
  // BFS outward.
  const W = map.width;
  const H = map.height;
  const visited = new Uint8Array(W * H);
  const queue: Array<[number, number]> = [[cx, cy]];
  let head = 0;
  while (head < queue.length) {
    const [x, y] = queue[head++] as [number, number];
    if (x < 0 || y < 0 || x >= W || y >= H) continue;
    const idx = y * W + x;
    if (visited[idx] === 1) continue;
    visited[idx] = 1;
    if (tiles[idx] === 1 && isWalkableTile(map.get(x, y))) return { x, y };
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        queue.push([x + dx, y + dy]);
      }
    }
  }
  return { x: cx, y: cy };
}

