    if (x < 0 || y < 0 || x >= W || y >= H) continue;
    const idx = y * W + x;
    if (visited2[idx] === 1) continue;
    visited2[idx] = 1;
    if (isWalkableTile(map.get(x, y))) return { x, y };
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        q2.push([x + dx, y + dy]);
      }
    }
  }
  return { x: cx, y: cy };
}

