function snapToWalkable(map: GameMap, tiles: Uint8Array, cx: number, cy: number): { x: number; y: number } {
  if (map.inBounds(cx, cy) && tiles[cy * map.width + cx] === 1 && isWalkableTile(map.get(cx, cy))) {
    return { x: cx, y: cy };
  }
  // BFS outward.
  const W = map.width;
  const H = map.height;
  const visited = new Uint8Array(W * H);
  const queue: Array<[number, number]> = [[cx, cy]];
  let head = 0;
  while (head < queue.length) {
    const [x, y] = queue[head++] as [number, number];
    if (x < 0 || y < 0 || x >= W || y >= H) continue;
    const idx = y * W + x;
    if (visited[idx] === 1) continue;
    visited[idx] = 1;
    if (tiles[idx] === 1 && isWalkableTile(map.get(x, y))) return { x, y };
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        queue.push([x + dx, y + dy]);
      }
    }
  }
  // Last resort: BFS ignoring tiles[] and just looking for any walkable neighbor.
  // This handles the case where the patch's flood.tiles has a hole at the
  // centroid and the BFS above fails to find a member of the patch within its
  // limited search depth.
  const visited2 = new Uint8Array(W * H);
  const q2: Array<[number, number]> = [[cx, cy]];
  let h2 = 0;
  while (h2 < q2.length) {
    const [x, y] = q2[h2++] as [number, number];
    if (x < 0 || y < 0 || x >= W || y >= H) continue;
    const idx = y * W + x;
    if (visited2[idx] === 1) continue;
    visited2[idx] = 1;
    if (isWalkableTile(map.get(x, y))) return { x, y };
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        q2.push([x + dx, y + dy]);
      }
    }
  }
  throw new Error(`snapToWalkable: nothing found for (${cx}, ${cy})`);
}

