import { describe, it, expect } from "vitest";
import { generateWfc, densitiesForLevel } from "../src/sim/wfc.js";
import { generatePlayableMap } from "../src/sim/playability.js";
import { makeRng } from "../src/sim/rng.js";
import { setupLevel } from "../src/sim/campaign.js";
import { isWalkableTile } from "../src/sim/tiles.js";
import { octile, landPathLength } from "../src/sim/pathfinding.js";

describe("wfc sanity", () => {
  it("level 1 produces a playable map", () => {
    let playable = 0;
    for (let i = 0; i < 10; i++) {
      const info = setupLevel(i * 100, 1);
      if (info.result.ok) playable++;
      else {
        const a = info.result.starts.a;
        const b = info.result.starts.b;
        const lin = octile(a.x, a.y, b.x, b.y);
        const land = landPathLength(info.result.map, a.x, a.y, b.x, b.y);
        console.log("seed", i*100, "size", info.size, "lin", lin.toFixed(2), "land", isFinite(land) ? land.toFixed(2) : "Inf", "starts", a, b);
      }
    }
    console.log("playable:", playable, "of 10");
    expect(playable).toBeGreaterThan(0);
  });
});

