function scoreStartArea(
  map: GameMap,
  cx: number,
  cy: number,
  reach: number,
): { hasGold: boolean; hasWood: boolean; goldCount: number; woodCount: number } {
  let hasGold = false;
  let hasWood = false;
  let goldCount = 0;
  let woodCount = 0;
  const w = map.width;
  const h = map.height;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const t = map.get(x, y);
      if (t !== TILE.GOLD_MINE && t !== TILE.FOREST) continue;
      // Use Chebyshev distance (max of dx, dy) for "near", since the spec says
      // "within 15 land-path tiles" but in practice the land path may detour
      // around water/rocks. Chebyshev is a generous upper bound.
      const dist = octile(x, y, cx, cy);
      if (dist > reach) continue;
      if (t === TILE.GOLD_MINE) {
        hasGold = true;
        goldCount++;
      } else {
        hasWood = true;
        woodCount++;
      }
    }
  }
  return { hasGold, hasWood, goldCount, woodCount };
}

