edits.newText:
function weightedPick(
  options: Set<TileType>,
  weights: Map<TileType, number>,
  rng: Rng,
): TileType {
  let total = 0;
  for (const t of options) total += weights.get(t) ?? 1;
  let r = rng.next() * total;
  for (const t of options) {
    r -= weights.get(t) ?? 1;
    if (r <= 0) return t;
  }
  // Fallback: first option
  return options.values().next().value as TileType;
}

function weightedShuffle(
  options: TileType[],
  weights: Map<TileType, number>,
  rng: Rng,
): TileType[] {
  // Sort descending by weight, then randomize within tolerance bands.
  const out = options.slice();
  out.sort((a, b) => (weights.get(b) ?? 1) - (weights.get(a) ?? 1));
  for (let i = 0; i < out.length; i++) {
    for (let j = i + 1; j < out.length; j++) {
      const wi = weights.get(out[i] as TileType) ?? 1;
      const wj = weights.get(out[j] as TileType) ?? 1;
      if (Math.abs(wi - wj) < 0.5 && rng.next() < 0.5) {
        const tmp = out[i] as TileType;
        out[i] = out[j] as TileType;
        out[j] = tmp;
      }
    }
  }
  return out;
}

