/** Adjacency rule: tile A may sit next to tile B. Indexed by tile id. */
export const ADJACENCY: Record<TileType, ReadonlySet<TileType>> = (() => {
  const all = new Set<TileType>([
    TILE.GRASS,
    TILE.DIRT,
    TILE.FOREST,
    TILE.WATER,
    TILE.ROCK,
    TILE.GOLD_MINE,
  ]);

  // Grass and dirt can be next to almost anything except GOLD_MINE borders anything
  // (mines are placed in clearings of grass/dirt only).
  const grass: TileType[] = [TILE.GRASS, TILE.DIRT, TILE.FOREST, TILE.WATER, TILE.ROCK, TILE.GOLD_MINE];
  const dirt: TileType[] = [TILE.GRASS, TILE.DIRT, TILE.FOREST, TILE.WATER, TILE.ROCK, TILE.GOLD_MINE];
  // Forest borders grass/dirt/forest only.
  const forest: TileType[] = [TILE.GRASS, TILE.DIRT, TILE.FOREST];
  // Water borders water/dirt only.
  const water: TileType[] = [TILE.WATER, TILE.DIRT];
  // Rock borders rock/grass/dirt/forest.
  const rock: TileType[] = [TILE.ROCK, TILE.GRASS, TILE.DIRT, TILE.FOREST];
  // Gold mines sit in clearings of grass/dirt only.
  const gold: TileType[] = [TILE.GRASS, TILE.DIRT];

  const build = (allow: TileType[]): ReadonlySet<TileType> => {
    const s = new Set<TileType>();
    for (const t of allow) s.add(t);
    // Always self-allow: tiles may cluster with their own type.
    void all;
    return s;
  };

  return {
    [TILE.GRASS]: build(grass),
    [TILE.DIRT]: build(dirt),
    [TILE.FOREST]: build(forest),
    [TILE.WATER]: build(water),
    [TILE.ROCK]: build(rock),
    [TILE.GOLD_MINE]: build(gold),
    [TILE.DEPLETED_MINE]: build([TILE.GRASS, TILE.DIRT, TILE.ROCK]),
    [TILE.STUMP]: build([TILE.GRASS, TILE.DIRT, TILE.FOREST, TILE.STUMP, TILE.ROCK]),
  };
})();

