import { describe, it, expect } from "vitest";
import { setupLevel } from "../src/sim/campaign.js";
import { TILE } from "../src/sim/tiles.js";

describe("wfc sanity", () => {
  it("level 1 produces a playable map", () => {
    let playable = 0;
    for (let i = 0; i < 10; i++) {
      const info = setupLevel(i * 100, 1);
      if (info.result.ok) playable++;
      else {
        const a = info.result.starts.a;
        const b = info.result.starts.b;
        const map = info.result.map;
        const near = (cx: number, cy: number) => {
          let gold = 0, forest = 0;
          for (let y = Math.max(0, cy-15); y <= Math.min(map.height-1, cy+15); y++) {
            for (let x = Math.max(0, cx-15); x <= Math.min(map.width-1, cx+15); x++) {
              const t = map.get(x, y);
              if (t === TILE.GOLD_MINE) gold++;
              if (t === TILE.FOREST) forest++;
            }
          }
          return { gold, forest };
        };
        // eslint-disable-next-line no-console
        console.log("seed", i*100, "starts", a, b, "nearA", near(a.x, a.y), "nearB", near(b.x, b.y), "issues", JSON.stringify(info.result.issues));
      }
    }
    // eslint-disable-next-line no-console
    console.log("playable:", playable, "of 10");
    expect(playable).toBeGreaterThan(0);
  });
});

